35	 * Выбирает ход за компьютер.
36	 * @returns {{from:string,to:string,promotion?:string,san:string,cp:number|null}|null}
37	 */
38	export async function chooseComputerMove(pool, fen, { level = 3, rng = null, signal = null } = {}) {
39	  const profile = getLevel(level);
40	  const analysis = await pool.analyse(
41	    { fen, nodes: profile.nodes, multipv: profile.multipv, newGame: true },
42	    { priority: 'urgent', signal },
43	  );
44	
45	  // Собираем кандидатов из MultiPV: первый ход каждой линии плюс bestmove как запасной.
46	  const chess = new Chess(fen);
47	  const legal = chess.moves({ verbose: true });
48	  const byUci = new Map(legal.map((m) => [`${m.from}${m.to}${m.promotion || ''}`, m]));
49	
50	  const candidates = [];
51	  for (const [idx, line] of analysis.multipv) {
52	    const uci = line.pv && line.pv[0];
53	    if (!uci) continue;
54	    const move = byUci.get(uci) || byUci.get(uci.slice(0, 4));
55	    if (!move) continue;
56	    candidates.push({ move, cp: scoreToCp(line.score), rank: idx });
57	  }
58	  if (candidates.length === 0 && analysis.best) {
59	    const move = byUci.get(analysis.best) || byUci.get(analysis.best.slice(0, 4));
60	    if (move) candidates.push({ move, cp: scoreToCp(analysis.score), rank: 1 });
61	  }
62	  if (candidates.length === 0) {
63	    // Движок не дал ничего пригодного — берём любой легальный ход, лишь бы партия шла.
64	    if (legal.length === 0) return null;
65	    const m = rng ? rng.pick(legal) : legal[0];
66	    return { from: m.from, to: m.to, promotion: m.promotion, san: m.san, cp: null };
67	  }
68	
69	  candidates.sort((a, b) => a.rank - b.rank);
70	  const bestCp = candidates[0].cp ?? 0;
71	  // Берём только те ходы, что не хуже лучшего больше чем на slackCp: даже слабый
72	  // уровень не должен «дарить» ферзя, иначе играть с ним неинтересно.
73	  const acceptable = candidates.filter((c) => (c.cp ?? bestCp) >= bestCp - profile.slackCp);
74	  const pick = rng ? rng.pick(acceptable) : acceptable[0];
75	
76	  return {
77	    from: pick.move.from,
78	    to: pick.move.to,
79	    promotion: pick.move.promotion,
80	    san: pick.move.san,
81	    cp: pick.cp,
82	    level: profile.id,
83	  };
84	}
