function hashSeed(seed) {
  const s = String(seed);
  let h1 = 0x9e3779b9;
  let h2 = 0x85ebca6b;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    h1 = Math.imul(h1 ^ c, 2654435761) >>> 0;
    h2 = Math.imul(h2 ^ ((c << 3) | (c >>> 5)), 1597334677) >>> 0;
  }
